"use client";
import { useEffect, useRef, useState } from "react";
import { Paperclip, Camera, Send, Smile } from "lucide-react";
import { PlaceholdersAndVanishInput } from "@/components/ui/placeholders-and-vanish-input";
import { Picker, EmojiType } from "ms-3d-emoji-picker";

export default function Home() {
  const [messages, setMessages] = useState([
    {
      id: 1,
      text: "Hello! How are you?",
      sender: "receiver",
      time: "10:05 AM",
    },
    {
      id: 2,
      text: "Hey! I'm good. What about you?",
      sender: "sender",
      time: "10:06 AM",
    },
    {
      id: 3,
      text: "I'm doing great, thanks!",
      sender: "receiver",
      time: "10:07 AM",
    },
  ]);
  type Message = {
    id: number;
    text: string;
    sender: "sender" | "receiver";
    time: string;
    file?: {
      name: string;
      type: string;
      url: string;
    } | null;
  };

  const [input, setInput] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [fileURL, setFileURL] = useState<string | null>(null);
  const [showPicker, setShowPicker] = useState<boolean>(false);
  const placeholder: string[] = ["Type a message..."];
  const messagesEndRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);
  useEffect(() => {
    return () => {
      if (fileURL) URL.revokeObjectURL(fileURL);
    };
  }, [fileURL]);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = event.target.files?.[0] || null;
    setFile(selectedFile);
    
    if (selectedFile) {
      const url = URL.createObjectURL(selectedFile);
      setFileURL(url);
    }
  };
  

  const handleSend = (): void => {
    if (input.trim() || file) {
      let fileURLToSend = file ? URL.createObjectURL(file) : null;

      const newMessage: Message = {
        id: messages.length + 1,
        text: input,
        sender: "sender",
        time: new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        }),
        file: file
          ? {
              name: file.name,
              type: file.type,
              url: fileURLToSend!,
            }
          : null,
      };

      setMessages([...messages, newMessage]);
      setInput("");
      setFile(null);
      setFileURL(null);
    }
  };

  return (
    <>
    <div className="relative bg-zinc-900">
      <div className="flex flex-col relative bg-zinc-900">
        <div className="overflow-y-auto  p-4 space-y-3">
          {messages.map((msg) => (
            <div
              key={msg.id}
              className={`flex ${
                msg.sender === "sender" ? "justify-end" : "justify-start"
              }`}
            >
              <div
                className={`p-3 max-w-xs sm:max-w-md md:max-w-lg lg:max-w-xl rounded-lg shadow-md ${
                  msg.sender === "sender"
                    ? "bg-blue-600 text-white rounded-br-none"
                    : "bg-zinc-700 text-white rounded-bl-none"
                }`}
              >
               
                  <p className="text-sm">{msg.text}</p>
                

                <span className="text-xs text-gray-300 block text-right mt-1">
                  {msg.time}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>
      <div className="fixed bottom-0 w-full">
        <div className="flex items-center w-fit gap-3 p-4 bg-zinc-900 border-t border-zinc-700 shadow-lg">
          <div className="relative">
            <button
              onClick={() => setShowPicker(!showPicker)}
              className="p-2 rounded-lg hover:bg-zinc-700 transition"
            >
              <Smile className="w-6 h-6 text-gray-400 hover:text-white" />
            </button>
            {showPicker && (
              <div className="absolute bottom-12 left-0 bg-zinc-800 shadow-lg rounded-lg">
                <Picker
                  isOpen={true}
                  handleEmojiSelect={(selectedEmoji: EmojiType) =>
                    setInput((prev) => prev + selectedEmoji)
                  }
                />
              </div>
            )}
          </div>
          <label
            htmlFor="camera"
            className="cursor-pointer p-2 rounded-lg hover:bg-zinc-700 transition"
          >
            <Camera className="w-6 h-6 text-gray-400 hover:text-white" />
            <input
              type="file"
              accept="image/*"
              capture="environment"
              id="camera"
              className="hidden"
              onChange={(e) => setFile(e.target.files?.[0] || null)}
            />
          </label>
          <div className="flex-1">
            <PlaceholdersAndVanishInput
              placeholders={["Type a message..."]}
              onChange={(e:any) => setInput(e.target.value)}
              onSubmit={(e:any) => {
                e.preventDefault();
                handleSend();
              }}
            />
          </div>
          <label
            htmlFor="file-upload"
            className="cursor-pointer p-2 rounded-lg hover:bg-zinc-700 transition"
          >
            <Paperclip className="w-6 h-6 text-gray-400 hover:text-white" />
            <input
              type="file"
              id="file-upload"
              className="hidden"
              onChange={(e) => setFile(e.target.files?.[0] || null)}
            />
          </label>
          <button
            className="p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
            onClick={handleSend}
          >
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
    </>
  );
}
